mapper.select:
select rm.*,rn.type_id,rn.info_name,iod.name from hotel_room as rm
inner join hotel_info as rn on rm.info_id = rn.info_id
left join into_order iod on iod.room_id = rm.room_id and iod.status = '1'
where 1=1

    and rn.type_id =#{parm.typeId}


    and rm.room_code =#{parm.roomCode}


    and rm.book_status =#{parm.bookStatus}

order by rm.room_code asc
